// ServerInterface represents all server handlers.
type ServerInterface interface {
	// 本域进程存活
	// (GET /healthz)
	Health(w http.ResponseWriter, r *http.Request)
	// 本域启动/恢复就绪
	// (GET /readyz)
	Ready(w http.ResponseWriter, r *http.Request)
	// 资源库列图片/附件/视频/画板及引用摘要
	// (GET /v1/assets)
	ListAssets(w http.ResponseWriter, r *http.Request, params ListAssetsParams)
	// 后台单列当前未引用文件
	// (GET /v1/assets/unused)
	ListUnusedAssets(w http.ResponseWriter, r *http.Request, params ListUnusedAssetsParams)
	// 读取资源/variants安全元数据
	// (GET /v1/assets/{assetId})
	ReadAsset(w http.ResponseWriter, r *http.Request, assetId Identifier, params ReadAssetParams)
	// 鉴权读取immutable bytes和Range
	// (GET /v1/assets/{assetId}/bytes)
	ReadAssetBytes(w http.ResponseWriter, r *http.Request, assetId Identifier, params ReadAssetBytesParams)
	// HEAD同GET授权只返header
	// (HEAD /v1/assets/{assetId}/bytes)
	HeadAssetBytes(w http.ResponseWriter, r *http.Request, assetId Identifier, params HeadAssetBytesParams)
	// 列哪些文档当前/历史引用资源
	// (GET /v1/assets/{assetId}/references)
	ReadAssetReferences(w http.ResponseWriter, r *http.Request, assetId Identifier)
	// 关联浏览器多宽WebP原图
	// (PUT /v1/assets/{assetId}/variants)
	AttachImageVariants(w http.ResponseWriter, r *http.Request, assetId Identifier)
	// 取得可恢复的数据屏障
	// (POST /v1/barriers)
	AcquireBarrier(w http.ResponseWriter, r *http.Request)
	// 释放屏障
	// (DELETE /v1/barriers/{barrierId})
	ReleaseBarrier(w http.ResponseWriter, r *http.Request, barrierId Identifier)
	// 人工清理前生成精确风险计划
	// (POST /v1/cleanup-plans)
	ProposeManualCleanup(w http.ResponseWriter, r *http.Request)
	// 删除前取消人工清理
	// (DELETE /v1/cleanup-plans/{planId})
	CancelManualCleanup(w http.ResponseWriter, r *http.Request, planId Identifier)
	// 管理员确认后进入迟到引用保护窗口
	// (POST /v1/cleanup-plans/{planId}:confirm)
	ConfirmManualCleanup(w http.ResponseWriter, r *http.Request, planId Identifier)
	// 给公开/管理员预览返回SHA URLs/srcset/封面
	// (POST /v1/delivery-manifests)
	BuildDeliveryManifest(w http.ResponseWriter, r *http.Request)
	// 正文/config提交前保护资源迟到引用
	// (POST /v1/references:acquire)
	AcquireResourceReferences(w http.ResponseWriter, r *http.Request)
	// 源提交后确认pin为引用
	// (POST /v1/references:confirm)
	ConfirmResourceReferences(w http.ResponseWriter, r *http.Request)
	// 仅明确源未提交才释放pin
	// (POST /v1/references:release)
	ReleaseResourceReferences(w http.ResponseWriter, r *http.Request)
	// 删除恢复暂存或换出的旧数据目录
	// (POST /v1/snapshots:discard)
	DiscardSnapshot(w http.ResponseWriter, r *http.Request)
	// 导出屏障水位的一致快照
	// (POST /v1/snapshots:export)
	ExportSnapshot(w http.ResponseWriter, r *http.Request)
	// 暂存本域恢复归档，不改active目录
	// (POST /v1/snapshots:stage)
	StageSnapshot(w http.ResponseWriter, r *http.Request)
	// 开始内容寻址可续传上传
	// (POST /v1/uploads)
	BeginUpload(w http.ResponseWriter, r *http.Request)
	// 取消未完成上传释放配额
	// (DELETE /v1/uploads/{uploadId})
	AbortUpload(w http.ResponseWriter, r *http.Request, uploadId Identifier)
	// 查询续传offset
	// (GET /v1/uploads/{uploadId})
	ReadUpload(w http.ResponseWriter, r *http.Request, uploadId Identifier)
	// 顺序原子写有界上传块
	// (PUT /v1/uploads/{uploadId}/chunks)
	PutUploadChunk(w http.ResponseWriter, r *http.Request, uploadId Identifier, params PutUploadChunkParams)
	// 完成hash/MIME验证后发布ready资源
	// (POST /v1/uploads/{uploadId}:complete)
	CompleteUpload(w http.ResponseWriter, r *http.Request, uploadId Identifier)
	// 插入时一次获取平台公开信息并本地封面
	// (POST /v1/videos/metadata)
	ReadVideoMetadata(w http.ResponseWriter, r *http.Request)
}

